#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Tcp
{
    std::uint16_t sourcePort;
    std::uint16_t destinationPort;
    std::uint32_t sequence;
    std::uint32_t acknowledgement;
    std::uint8_t headerLength;
    std::uint8_t flags;
    std::uint16_t window;
    std::optional<std::uint16_t> mss;
    std::optional<std::uint8_t> windowScale;
    bool sackPermitted;
};

namespace
{
    std::uint16_t be16(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return static_cast<std::uint16_t>((b[i] << 8) | b[i + 1]);
    }

    std::uint32_t be32(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return (std::uint32_t{ be16(b, i) } << 16) | be16(b, i + 2);
    }
}

std::optional<Tcp> parseTcp(const std::vector<std::uint8_t>& s)
{
    if (s.size() < 20) return std::nullopt;
    Tcp t{};
    t.sourcePort = be16(s, 0);
    t.destinationPort = be16(s, 2);
    t.sequence = be32(s, 4);
    t.acknowledgement = be32(s, 8);
    t.headerLength = static_cast<std::uint8_t>((s[12] >> 4) * 4);
    if (t.headerLength < 20 || t.headerLength > s.size()) return std::nullopt;
    t.flags = s[13];
    t.window = be16(s, 14);
    std::size_t i{ 20 };
    while (i < t.headerLength)
    {
        const std::uint8_t kind{ s[i] };
        if (kind == 0) break;
        if (kind == 1) { ++i; continue; }
        if (i + 1 >= t.headerLength) return std::nullopt;
        const std::size_t length{ s[i + 1] };
        if (length < 2 || i + length > t.headerLength) return std::nullopt;
        if (kind == 2 && length == 4) t.mss = be16(s, i + 2);
        else if (kind == 3 && length == 3) t.windowScale = s[i + 2];
        else if (kind == 4 && length == 2) t.sackPermitted = true;
        i += length;
    }
    return t;
}

std::string flagNames(std::uint8_t flags)
{
    const char* names[]{ "FIN", "SYN", "RST", "PSH", "ACK", "URG", "ECE", "CWR" };
    std::string s;
    for (int bit{ 0 }; bit < 8; ++bit)
    {
        if ((flags & (1 << bit)) == 0) continue;
        if (!s.empty()) s += ',';
        s += names[bit];
    }
    return s;
}

std::uint16_t transportChecksum(std::uint32_t source, std::uint32_t destination, std::uint8_t protocol,
                                const std::vector<std::uint8_t>& segment)
{
    const auto length{ static_cast<std::uint16_t>(segment.size()) };
    std::vector<std::uint8_t> data{
        static_cast<std::uint8_t>(source >> 24), static_cast<std::uint8_t>(source >> 16),
        static_cast<std::uint8_t>(source >> 8), static_cast<std::uint8_t>(source),
        static_cast<std::uint8_t>(destination >> 24), static_cast<std::uint8_t>(destination >> 16),
        static_cast<std::uint8_t>(destination >> 8), static_cast<std::uint8_t>(destination),
        0, protocol, static_cast<std::uint8_t>(length >> 8), static_cast<std::uint8_t>(length) };
    data.insert(data.end(), segment.begin(), segment.end());
    std::uint32_t sum{ 0 };
    for (std::size_t i{ 0 }; i < data.size(); i += 2)
    {
        sum += (std::uint32_t{ data[i] } << 8) | (i + 1 < data.size() ? data[i + 1] : 0u);
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return static_cast<std::uint16_t>(~sum & 0xFFFF);
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
Bytes synSegment() {
    return { 0xC3, 0x50, 0x00, 0x50, 0x00, 0x00, 0x00, 0x64, 0x00, 0x00, 0x00, 0x00,
             0x80, 0x02, 0xFA, 0xF0, 0x00, 0x00, 0x00, 0x00,
             0x02, 0x04, 0x05, 0xB4, 0x01, 0x03, 0x03, 0x08, 0x04, 0x02, 0x01, 0x01 };
}
TEST("a SYN with options") {
    const auto t{ parseTcp(synSegment()) };
    CHECK(t.has_value());
    if (t) {
        CHECK_EQ(t->sourcePort, 50000);
        CHECK_EQ(t->destinationPort, 80);
        CHECK_EQ(t->sequence, 100u);
        CHECK_EQ(t->acknowledgement, 0u);
        CHECK_EQ(t->headerLength, 32);
        CHECK_EQ(t->flags, 0x02);
        CHECK_EQ(t->window, 64240);
        CHECK(t->mss == std::optional<std::uint16_t>{ 1460 });
        CHECK(t->windowScale == std::optional<std::uint8_t>{ 8 });
        CHECK(t->sackPermitted);
    }
}
TEST("headers without options, with data, and with an end marker") {
    Bytes plain(20, 0); plain[12] = 0x50; plain[13] = 0x18;
    plain.insert(plain.end(), { 'h', 'i' });
    const auto t{ parseTcp(plain) };
    CHECK(t.has_value() && t->headerLength == 20 && !t->mss && !t->sackPermitted);
    Bytes ended(24, 0); ended[12] = 0x60; ended[20] = 0; ended[21] = 0xFF; ended[22] = 0xFF; ended[23] = 0xFF;
    CHECK(parseTcp(ended).has_value());
}
TEST("broken options and lengths") {
    Bytes longOption{ synSegment() }; longOption[21] = 0x10;
    CHECK(!parseTcp(longOption).has_value());
    Bytes tinyOption{ synSegment() }; tinyOption[21] = 1;
    CHECK(!parseTcp(tinyOption).has_value());
    Bytes lastByte(24, 0); lastByte[12] = 0x60; lastByte[20] = 1; lastByte[21] = 1; lastByte[22] = 1; lastByte[23] = 2;
    CHECK(!parseTcp(lastByte).has_value());
    Bytes offset{ synSegment() }; offset[12] = 0xF0;
    CHECK(!parseTcp(offset).has_value());
    Bytes small{ synSegment() }; small[12] = 0x40;
    CHECK(!parseTcp(small).has_value());
    CHECK(!parseTcp(Bytes(19, 0)).has_value());
}
TEST("flag names") {
    CHECK_EQ(flagNames(0x12), std::string("SYN,ACK"));
    CHECK_EQ(flagNames(0x18), std::string("PSH,ACK"));
    CHECK_EQ(flagNames(0x11), std::string("FIN,ACK"));
    CHECK_EQ(flagNames(0x04), std::string("RST"));
    CHECK_EQ(flagNames(0xC2), std::string("SYN,ECE,CWR"));
    CHECK_EQ(flagNames(0), std::string(""));
}
TEST("the pseudo-header checksum") {
    CHECK_EQ(transportChecksum(0, 0, 17, { 0, 0, 0, 0, 0, 8, 0, 0 }), 0xFFDE);
    for (std::size_t extra : { 0u, 1u, 2u }) {
        Bytes s{ synSegment() };
        for (std::size_t i{ 0 }; i < extra; ++i) s.push_back(static_cast<std::uint8_t>(0x41 + i));
        const std::uint16_t sum{ transportChecksum(0x0A000002, 0x5DB8D822, 6, s) };
        s[16] = static_cast<std::uint8_t>(sum >> 8);
        s[17] = static_cast<std::uint8_t>(sum);
        CHECK_EQ(transportChecksum(0x0A000002, 0x5DB8D822, 6, s), 0);
        CHECK(transportChecksum(0x0A000003, 0x5DB8D822, 6, s) != 0);
    }
}

